function wpbp_auth_003( int $user_id, string $application_name ) {
	$existing = wp_get_application_passwords( $user_id );
	foreach ( $existing as $app ) {
		if ( $app['name'] === $application_name ) {
			return new WP_Error( 'wpbp_duplicate_name', 'An application password with that name already exists.' );
		}
	}
	$password = wp_create_application_password( $user_id, array( 'name' => $application_name ) );
	if ( is_wp_error( $password ) ) {
		return $password;
	}
	return implode( ' ', str_split( $password, 4 ) );
}
