function wpbp_auth_005( int $user_id, string $password ): string {
    $user = get_user_by( 'id', $user_id );
    if ( ! $user ) {
        return 'invalid';
    }
    $hash = $user->user_pass;
    if ( ! wp_check_password( $password, $hash, $user_id ) ) {
        return 'invalid';
    }
    if ( wp_password_needs_rehash( $hash ) ) {
        wp_set_password( $password, $user_id );
        return 'rehashed';
    }
    return 'current';
}
