function wpbp_cron_007(string $hook, array $args) {
    $cron = get_option('cron');
    if (!is_array($cron)) return false;
    $next = false;
    $found = null;
    foreach ($cron as $timestamp => $hooks) {
        if (!is_array($hooks) || !isset($hooks[$hook])) continue;
        foreach ($hooks[$hook] as $event) {
            if (isset($event['args']) && $event['args'] === $args) {
                if ($next === false || $timestamp < $next) {
                    $next = $timestamp;
                    $found = $event;
                }
            }
        }
    }
    if ($found === null) return false;
    return [
        'timestamp' => $next,
        'schedule' => $found['schedule'] ?? false,
        'interval' => $found['interval'] ?? 0,
    ];
}
