function wpbp_dates_time_005( string $utc_datetime ): string {
    $date = new DateTime( $utc_datetime, new DateTimeZone( 'UTC' ) );
    $tz_string = get_option( 'timezone_string' );
    if ( $tz_string ) {
        $tz = new DateTimeZone( $tz_string );
    } else {
        $offset = (float) get_option( 'gmt_offset' );
        $hours = (int) $offset;
        $mins = abs( ( $offset - $hours ) * 60 );
        $sign = $offset >= 0 ? '+' : '-';
        $tz = new DateTimeZone( sprintf( 'UTC%s%02d:%02d', $sign, abs( $hours ), $mins ) );
    }
    $date->setTimezone( $tz );
    return $date->format( 'c' );
}
