function wpbp_gb_interactivity_api_009( array $settings ): array {
    $store = 'wpbp/merge';
    $state = wp_interactivity_state( $store ) ?? [];
    if ( ! isset( $state['settings'] ) || ! is_array( $state['settings'] ) ) {
        $state['settings'] = [];
    }
    $state['settings'] = array_replace_recursive( $state['settings'], $settings );
    wp_interactivity_state( $store, $state );
    return $state;
}
