<?php
function wpbp_html_api_001( string $html ): string {
	$site_host = parse_url( home_url(), PHP_URL_HOST );
	$processor = new WP_HTML_Tag_Processor( $html );
	$modified  = false;
	while ( $processor->next_tag( array( 'tag_name' => 'A' ) ) ) {
		$href = $processor->get_attribute( 'href' );
		if ( ! $href ) {
			continue;
		}
		$host = parse_url( $href, PHP_URL_HOST );
		if ( ! $host || strtolower( $host ) === strtolower( $site_host ) ) {
			continue;
		}
		if ( 0 === strpos( $href, '/' ) || 0 === strpos( $href, '#' ) || 0 === stripos( $href, 'mailto:' ) ) {
			continue;
		}
		$rel = $processor->get_attribute( 'rel' );
		if ( $rel ) {
			if ( false === stripos( ' ' . $rel . ' ', ' noopener ' ) ) {
				$processor->set_attribute( 'rel', $rel . ' noopener' );
				$modified = true;
			}
		} else {
			$processor->set_attribute( 'rel', 'noopener' );
			$modified = true;
		}
	}
	return $modified ? $processor->get_updated_html() : $html;
}
