/**
 * Plugin Name: WPBP Reader
 * Description: Handles reader settings lifecycle.
 * Version: 2.0
 */

function wpbp_reader_activate() {
    $settings = get_option('wpbp_reader_settings');
    if ($settings === false) {
        $defaults = array(
            'version'     => 2,
            'per_page'    => 10,
            'show_covers' => true,
        );
        add_option('wpbp_reader_settings', $defaults);
    }
}
register_activation_hook(__FILE__, 'wpbp_reader_activate');

function wpbp_reader_upgrade() {
    $settings = get_option('wpbp_reader_settings');
    if ($settings && (!isset($settings['version']) || $settings['version'] < 2)) {
        $new_settings = array(
            'version'     => 2,
            'per_page'    => isset($settings['perPage']) ? $settings['perPage'] : 10,
            'show_covers' => true,
        );
        update_option('wpbp_reader_settings', $new_settings);
        $upgrades = get_option('wpbp_reader_upgrades', 0);
        update_option('wpbp_reader_upgrades', $upgrades + 1);
    }
}
add_action('plugins_loaded', 'wpbp_reader_upgrade');

function wpbp_reader_uninstall() {
    delete_option('wpbp_reader_settings');
    delete_option('wpbp_reader_upgrades');
}
register_uninstall_hook(__FILE__, 'wpbp_reader_uninstall');
