<?php
function wpbp_post_types_taxonomy_010( int $term_id, string $new_name ): string {
	$taxonomy = 'category';
	$desired_slug = sanitize_title( $new_name );
	$term = get_term( $term_id, $taxonomy );
	if ( ! $term || is_wp_error( $term ) ) {
		return '';
	}
	$unique_slug = wp_unique_term_slug( $desired_slug, (object) [
		'term_id'  => $term_id,
		'taxonomy' => $taxonomy,
	] );
	$result = wp_update_term( $term_id, $taxonomy, [
		'name' => $new_name,
		'slug' => $unique_slug,
	] );
	if ( is_wp_error( $result ) ) {
		return '';
	}
	$updated = get_term( $term_id, $taxonomy );
	return $updated && ! is_wp_error( $updated ) ? $updated->slug : '';
}
