    $postarr = [
        'post_title'   => $title,
        'post_status'  => 'future',
        'post_date'    => $local->format( 'Y-m-d H:i:s' ),
        'post_date_gmt'=> $utc_datetime,
        'post_type'    => 'post',
    ];
    $id = wp_insert_post( $postarr );
    if ( $id && ! wp_next_scheduled( 'publish_future_post', [ $id ] ) ) {
        wp_schedule_single_event( strtotime( $utc_datetime ), 'publish_future_post', [ $id ] );
    }
    return (int) $id;
}
