function wpbp_rewrite_permalinks_006(): void {
    add_filter('query_vars', static function (array $vars): array {
        $vars[] = 'wpbp_archive';
        return $vars;
    });
    add_filter('rewrite_rules_array', static function (array $rules): array {
        $new = ['wpbp-archive/?$' => 'index.php?wpbp_archive=1'];
        $result = [];
        $inserted = false;
        foreach ($rules as $k => $v) {
            if (!$inserted && preg_match('#\(\[\^/\]\+\)\(\?:/\(\[0-9\]\+\)\)\)\?/?\$$#', $k)) {
                $result += $new;
                $inserted = true;
            }
            $result[$k] = $v;
        }
        if (!$inserted) {
            $result += $new;
        }
        return $result;
    });
}
