<?php
function wpbp_settings_options_007(array $autoload_map): array {
    global $wpdb;
    if (empty($autoload_map)) {
        return [];
    }
    $names = array_keys($autoload_map);
    $placeholders = implode(',', array_fill(0, count($names), '%s'));
    $table = $wpdb->options;
    $current = $wpdb->get_results(
        $wpdb->prepare(
            "SELECT option_name, autoload FROM {$table} WHERE option_name IN ({$placeholders})",
            $names
        ),
        OBJECT_K
    );
    $to_update = [];
    $result = [];
    foreach ($autoload_map as $name => $desired) {
        $desired_str = $desired ? 'yes' : 'no';
        if (isset($current[$name])) {
            $current_str = $current[$name]->autoload;
            $changed = ($current_str !== $desired_str);
            $result[$name] = $changed;
            if ($changed) {
                $to_update[$name] = $desired_str;
            }
        } else {
            $result[$name] = false;
        }
    }
    if (!empty($to_update)) {
        $case_parts = [];
        $in_names = [];
        foreach ($to_update as $name => $val) {
            $case_parts[] = $wpdb->prepare("WHEN option_name = %s THEN %s", $name, $val);
            $in_names[] = $name;
        }
        $case_sql = implode(' ', $case_parts);
        $in_placeholders = implode(',', array_fill(0, count($in_names), '%s'));
        $wpdb->query(
            $wpdb->prepare(
                "UPDATE {$table} SET autoload = CASE {$case_sql} END WHERE option_name IN ({$in_placeholders})",
                $in_names
            )
        );
    }
    return $result;
}
