<?php
function wpbp_settings_options_009( array $option_names ): array {
    if ( empty( $option_names ) ) {
        return [];
    }
    global $wpdb;
    $placeholders = implode( ',', array_fill( 0, count( $option_names ), '%s' ) );
    $sql = "SELECT option_name, option_value FROM {$wpdb->options} WHERE option_name IN ($placeholders)";
    $prepared = $wpdb->prepare( $sql, $option_names );
    $rows = $wpdb->get_results( $prepared, ARRAY_A );
    $found = [];
    foreach ( $rows as $row ) {
        $found[ $row['option_name'] ] = maybe_unserialize( $row['option_value'] );
    }
    $result = [];
    foreach ( $option_names as $name ) {
        $result[ $name ] = $found[ $name ] ?? false;
    }
    return $result;
}
