<?php
function wpbp_theme_templates_002( string $template_slug ): string {
    $theme = get_stylesheet();
    $candidates = [$template_slug];
    $base = explode('-', $template_slug, 2)[0];
    if ($base !== $template_slug) {
        $candidates[] = $base;
    }
    if (in_array($base, ['single', 'page', 'attachment'], true)) {
        $candidates[] = 'singular';
    } elseif (in_array($base, ['category', 'tag', 'taxonomy', 'author', 'date', 'archive'], true)) {
        $candidates[] = 'archive';
    }
    if ($template_slug !== 'home' && $template_slug !== 'front-page') {
        $candidates[] = 'home';
    }
    $candidates[] = 'index';
    $candidates = array_values(array_unique($candidates));
    foreach ($candidates as $slug) {
        if (get_block_template($theme . '//' . $slug, 'wp_template')) {
            return $slug;
        }
        if (file_exists(get_theme_file_path('templates/' . $slug . '.html'))) {
            return $slug;
        }
    }
    return 'index';
}
