    $home_host = parse_url( home_url(), PHP_URL_HOST );
    $item_host = ! empty( $item->url ) ? parse_url( $item->url, PHP_URL_HOST ) : null;
    if ( $item_host && $item_host !== $home_host ) {
        $atts['target'] = '_blank';
        $atts['rel']    = 'noopener nofollow';
    }
    return $atts;
}, 10, 4 );
